1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireArea } from "@/lib/rbac";
4	import { PageHeader, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
5	import { MigrationRemediationControls } from "@/components/admin/MigrationRemediationControls";
6	
7	export const dynamic = "force-dynamic";
8	
9	const statusTone: Record<string, "slate" | "brand" | "amber" | "green" | "red"> = {
10	  RUNNING: "brand",
11	  PENDING: "slate",
12	  DONE: "green",
13	  COMPLETED_WITH_ISSUES: "amber",
14	  FAILED: "red",
15	};
16	
17	/** Domains a run flagged as not serving, pulled from the persisted step results. */
18	function darkDomains(items: unknown): string[] {
19	  const results = ((items ?? {}) as { results?: { step?: string; status?: string }[] }).results ?? [];
20	  const out: string[] = [];
21	  for (const r of results) {
22	    const m = /^Site (.+?) is NOT serving$/.exec(String(r?.step ?? ""));
23	    if (m) out.push(m[1]);
24	  }
25	  return out;
26	}
