28	export default async function AdminMigrationsPage() {
29	  await requireArea("fleet");
30	
31	  // Migrations that need a human (or that a human should watch), newest first.
32	  const rows = await db.migration.findMany({
33	    where: { status: { in: ["COMPLETED_WITH_ISSUES", "FAILED", "RUNNING"] } },
34	    orderBy: { createdAt: "desc" },
35	    take: 100,
36	    select: {
37	      id: true, userId: true, serverId: true, sourceHost: true, status: true,
38	      step: true, lastError: true, items: true, createdAt: true, finishedAt: true,
39	    },
40	  });
41	
42	  const userIds = [...new Set(rows.map((r) => r.userId))];
43	  const serverIds = [...new Set(rows.map((r) => r.serverId))];
44	  const [users, servers] = await Promise.all([
45	    db.user.findMany({ where: { id: { in: userIds } }, select: { id: true, email: true } }),
46	    db.server.findMany({ where: { id: { in: serverIds } }, select: { id: true, hostname: true, label: true, ipAddress: true } }),
47	  ]);
48	  const userById = new Map(users.map((u) => [u.id, u]));
49	  const serverById = new Map(servers.map((s) => [s.id, s]));
50	
51	  const needAttention = rows.filter((r) => r.status !== "RUNNING");
52	
53	  return (
54	    <div className="space-y-6">
55	      <PageHeader
56	        title="Migrations"
57	        sub="Customer migrations that finished with issues or failed — finish them here, over the platform's own SSH, so the customer doesn't have to."
58	      />
59	
60	      {needAttention.length === 0 ? (
61	        <EmptyState title="Nothing needs attention" sub="No migration is currently stuck. Runs in progress appear below." />
62	      ) : (
63	        <div className="space-y-4">
64	          {needAttention.map((r) => {
65	            const user = userById.get(r.userId);
66	            const server = serverById.get(r.serverId);
67	            const dark = darkDomains(r.items);
68	            return (
69	              <div key={r.id} className="card">
70	                <div className="flex flex-wrap items-center justify-between gap-2">
71	                  <div className="flex items-center gap-2">
72	                    <Badge tone={statusTone[r.status] ?? "slate"}>{r.status.replace(/_/g, " ")}</Badge>
73	                    <span className="font-medium text-slate-200">{server ? server.label || server.hostname : r.serverId}</span>
74	                    {server?.ipAddress && <span className="text-xs text-slate-500">{server.ipAddress}</span>}
75	                  </div>
76	                  <span className="text-xs text-slate-500">{timeAgo(r.finishedAt ?? r.createdAt)}</span>
77	                </div>
78	
79	                <p className="mt-1 text-xs text-slate-500">
80	                  {user?.email ?? r.userId} · from {r.sourceHost}
81	                </p>
82	
83	                {r.step && <p className="mt-2 text-sm text-slate-300">{r.step}</p>}
84	                {r.lastError && <p className="mt-1 text-sm text-red-300">{r.lastError}</p>}
85	
86	                {dark.length > 0 && (
87	                  <p className="mt-2 text-sm">
88	                    <span className="text-amber-300">Not serving:</span>{" "}
89	                    <span className="text-slate-400">{dark.join(", ")}</span>
90	                  </p>
91	                )}
92	
93	                <div className="mt-2 flex items-center gap-3">
94	                  <Link href={`/admin/servers`} className="text-xs text-brand-300 hover:underline">
95	                    View server →
96	                  </Link>
97	                </div>
98	
99	                <MigrationRemediationControls migrationId={r.id} />
100	              </div>
101	            );
102	          })}
103	        </div>
104	      )}
105	
106	      {rows.some((r) => r.status === "RUNNING") && (
107	        <div className="card">
108	          <h3 className="mb-2 text-sm font-semibold text-slate-300">In progress</h3>
109	          <ul className="space-y-1 text-xs text-slate-400">
110	            {rows.filter((r) => r.status === "RUNNING").map((r) => {
111	              const server = serverById.get(r.serverId);
112	              return (
113	                <li key={r.id} className="flex items-center justify-between">
114	                  <span>{server ? server.label || server.hostname : r.serverId} — {r.step ?? "…"}</span>
115	                  <span className="text-slate-600">{timeAgo(r.createdAt)}</span>
116	                </li>
117	              );
118	            })}
119	          </ul>
120	        </div>
121	      )}
122	    </div>
123	  );
124	}
