1	import Link from "next/link";
2	import { requireArea } from "@/lib/rbac";
3	import { db } from "@/lib/db";
4	import { PageHeader, StatCard, fmtMoney, timeAgo } from "@/components/ui/primitives";
5	import { InvoiceStatusBadge } from "@/components/customer/InvoiceViews";
6	import { RegenerateMissingButton } from "@/components/admin/InvoiceAdmin";
7	import { BulkTable, type BulkRow } from "@/components/admin/BulkTable";
8	import { bulkVoidInvoices } from "@/lib/actions-admin-billing";
9	import { formatInvoiceNumber, invoiceBranding } from "@/lib/invoices";
10	import { paginate, pageHref } from "@/lib/pagination";
11	import type { InvoiceStatus } from "@prisma/client";
12	
13	export const dynamic = "force-dynamic";
14	
15	const STATUSES: InvoiceStatus[] = ["OPEN", "PAID", "VOID", "REFUNDED"];
16	const PER_PAGE = 25;
17	
18	export default async function AdminInvoices({
19	  searchParams,
20	}: {
21	  searchParams: Promise<{ status?: string; page?: string }>;
22	}) {
23	  await requireArea("billing");
24	  const sp = await searchParams;
25	  const status = STATUSES.includes(sp.status as InvoiceStatus)
26	    ? (sp.status as InvoiceStatus)
27	    : undefined;
28	  const where = status ? { status } : {};
29	
30	  const [total, issued, paid, outstanding] = await Promise.all([
31	    db.invoice.count({ where }),
32	    db.invoice.aggregate({ where: { status: { not: "VOID" } }, _sum: { amountCents: true } }),
33	    db.invoice.aggregate({ where: { status: "PAID" }, _sum: { amountCents: true } }),
34	    db.invoice.aggregate({ where: { status: "OPEN" }, _sum: { amountCents: true } }),
35	  ]);
36	
37	  const pg = paginate(sp, total, PER_PAGE);
38	  const invoices = await db.invoice.findMany({
39	    where,
40	    include: { user: { select: { id: true, email: true, name: true } } },
41	    orderBy: { createdAt: "desc" },
42	    skip: pg.skip,
43	    take: pg.take,
44	  });
45	
46	  const chip = (href: string, label: string, active: boolean) => (
47	    <Link
48	      href={href}
49	      className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
50	        active
51	          ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
52	          : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
53	      }`}
54	    >
55	      {label}
56	    </Link>
57	  );
58	
59	  const exportHref = `/api/admin/export?type=invoices${status ? `&status=${status}` : ""}`;
60	  const filterParams = { status };
61	
62	  // One settings read for the whole page; the prefix is per-platform, not per-invoice.
63	  const { numberPrefix } = await invoiceBranding();
64	
65	  const rows: BulkRow[] = invoices.map((inv) => ({
66	    id: inv.id,
67	    // Only OPEN/REFUNDED invoices can be bulk-voided.
68	    selectable: inv.status === "OPEN" || inv.status === "REFUNDED",
69	    cells: [
70	      <Link key="n" href={`/admin/invoices/${inv.id}`} className="font-mono text-xs text-slate-300 hover:text-brand-300">
71	        {formatInvoiceNumber(inv.number, numberPrefix)}
72	      </Link>,
73	      <Link key="c" href={`/admin/users/${inv.user.id}`} className="hover:text-brand-300">
74	        {inv.user.email}
75	      </Link>,
76	      <Link key="d" href={`/admin/invoices/${inv.id}`} className="block max-w-xs truncate hover:text-brand-300">
77	        {inv.description}
78	      </Link>,
79	      <InvoiceStatusBadge key="s" status={inv.status} />,
80	      <span key="a" className="font-mono">{fmtMoney(inv.amountCents)}</span>,
81	      <span key="t" className="text-xs text-slate-400" title={inv.createdAt.toISOString()}>
82	        {timeAgo(inv.createdAt)}
83	      </span>,
84	    ],
85	  }));
86	
87	  return (
88	    <div className="space-y-6">
89	      <PageHeader title="Invoices" sub="All billing documents issued across the platform.">
90	        <Link href="/admin/billing" className="btn-ghost py-1.5">
91	          Billing
92	        </Link>
93	        <RegenerateMissingButton />
94	      </PageHeader>
95	
96	      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
97	        <StatCard label="Issued · total" value={fmtMoney(issued._sum.amountCents ?? 0)} delta="excl. void" />
98	        <StatCard label="Paid" value={fmtMoney(paid._sum.amountCents ?? 0)} />
99	        <StatCard label="Outstanding" value={fmtMoney(outstanding._sum.amountCents ?? 0)} delta="open" deltaGood={false} />
100	        <StatCard label="Count" value={String(total)} delta={status ? `filtered: ${status.toLowerCase()}` : "all statuses"} />
101	      </div>
102	
103	      <div className="card p-0">
104	        <div className="flex flex-wrap items-center justify-end gap-2 px-5 pt-5">
105	          {chip("/admin/invoices", "All", !status)}
106	          {STATUSES.map((s) =>
107	            chip(`/admin/invoices?status=${s}`, s.charAt(0) + s.slice(1).toLowerCase(), status === s)
108	          )}
109	        </div>
110	
111	        <BulkTable
112	          columns={[
113	            { header: "Number" },
114	            { header: "Client" },
115	            { header: "Description" },
116	            { header: "Status" },
117	            { header: "Amount", className: "text-right" },
118	            { header: "Issued", className: "text-right" },
119	          ]}
120	          rows={rows}
121	          exportHref={exportHref}
122	          minWidth={760}
123	          empty="No invoices found."
124	          actions={[
125	            {
126	              label: "Void",
127	              danger: true,
128	              confirm: "Void the selected open invoices? They will no longer be collectible.",
129	              run: bulkVoidInvoices,
130	            },
131	          ]}
132	        />
133	
134	        <div className="flex items-center justify-between gap-3 px-5 py-4 text-xs text-slate-500">
135	          <span>
136	            Page {pg.page} of {pg.pages} · {total} invoice{total === 1 ? "" : "s"}
137	          </span>
138	          <div className="flex items-center gap-2">
139	            {pg.page > 1 && (
140	              <Link href={pageHref("/admin/invoices", filterParams, pg.page - 1)} className="btn-ghost py-1 text-xs">
141	                ← Prev
142	              </Link>
143	            )}
144	            {pg.page < pg.pages && (
145	              <Link href={pageHref("/admin/invoices", filterParams, pg.page + 1)} className="btn-ghost py-1 text-xs">
146	                Next →
147	              </Link>
148	            )}
149	          </div>
150	        </div>
151	      </div>
152	    </div>
153	  );
154	}
